    .wa-meter {
      position: relative;
      height: .42rem;
      overflow: hidden;
      border-radius: 999px;
      background: rgba(255, 255, 255, .07);
    }
    .wa-meter > span {
      position: absolute;
      left: 50%;
      top: 0;
      bottom: 0;
      width: 0;
      border-radius: inherit;
      background: linear-gradient(90deg, var(--wa-soul), var(--wa-blue));
      transition: width .3s ease, left .3s ease;
